import java.util.Scanner;
import java.util.Arrays;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) return;
        int n = scanner.nextInt();
        int[] vals = new int[n];
        for (int i = 0; i < n; i++) {
            vals[i] = scanner.nextInt();
        }

        Arrays.sort(vals);
        long bestPrice = 0;
        long maxRev = -1;

        for (int i = 0; i < n; i++) {
            if (i > 0 && vals[i] == vals[i-1]) continue;
            long p = vals[i];
            long buyers = n - i;
            long rev = p * buyers;

            if (rev > maxRev) {
                maxRev = rev;
                bestPrice = p;
            }
        }

        System.out.println(bestPrice + " " + maxRev);
    }
}

