#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    int n;
    if (!(cin >> n)) return 0;
    vector<long long> vals(n);
    for (int i = 0; i < n; i++) {
        cin >> vals[i];
    }

    sort(vals.begin(), vals.end());
    long long best_price = 0;
    long long max_rev = -1;

    for (int i = 0; i < n; i++) {
        if (i > 0 && vals[i] == vals[i-1]) continue;
        long long p = vals[i];
        long long buyers = n - i;
        long long rev = p * buyers;

        if (rev > max_rev) {
            max_rev = rev;
            best_price = p;
        }
    }

    cout << best_price << " " << max_rev << "\n";
    return 0;
}
